fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars = txt.chars();

    // Must be non-empty
    let last = match chars.next_back() {
        Some(c) => c,
        None => return false,
    };

    // Last character must be an ASCII alphabetic letter
    if !last.is_ascii_alphabetic() {
        return false;
    }

    // Either single character, or preceding character is a space
    match chars.next_back() {
        None => true,
        Some(prev) => prev == ' ',
    }
}